import numpy as np, itertools
e=df['eps'].values; t=df['T'].values; s=df['sigma'].values
F={'1':np.ones_like(e),'e':e,'e2':e**2,'sqrte':np.sqrt(e),'loge':np.log(e),'1/e':1/e,'exp-e':np.exp(-e),'1/(1+e)':1/(1+e),'e^1.5':e**1.5}
G={'1':np.ones_like(t),'T':t,'T2':t**2,'T3':t**3,'1/T':1/t,'lnT':np.log(t),'T^-2':t**-2,'sqrtT':np.sqrt(t),'expT':np.exp(t),'exp-T':np.exp(-t),'T^4':t**4}
cands={}
for fn,fv in F.items():
    for gn,gv in G.items():
        cands[fn+'*'+gn]=fv*gv
best=[]
names=list(cands)
for b in np.linspace(0.05,3,60):
    base=t**3/(1+b*e)
    for n1,n2 in itertools.combinations(names,2):
        A=np.c_[base,cands[n1],cands[n2]]
        c,*_=np.linalg.lstsq(A,s,rcond=None)
        mse=np.mean((A@c-s)**2)/np.var(s)
        best.append((mse,b,n1,n2,c))
best.sort(key=lambda x:x[0])
for r in best[:8]: print(r[0],r[1],r[2],r[3],np.round(r[4],4))
